package com.tecsup.medico.controller; import com.tecsup.medico.model.Medico;import com.tecsup.medico.model.Especialidad;import com.tecsup.medico.repository.MedicoRepository;import com.tecsup.medico.repository.EspecialidadRepository;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController@RequestMapping("/api/medicos")public class MedicoController{private final MedicoRepository r;private final EspecialidadRepository er;public MedicoController(MedicoRepository r,EspecialidadRepository er){this.r=r;this.er=er;}@GetMapping public List<Medico>listar(){return r.findAll();}@GetMapping("/{id}")public Medico obtener(@PathVariable Long id){return r.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Médico no encontrado"));}@PostMapping@ResponseStatus(HttpStatus.CREATED)public Medico crear(@Valid@RequestBody MedicoRequest d){return r.save(map(new Medico(),d));}@PutMapping("/{id}")public Medico actualizar(@PathVariable Long id,@Valid@RequestBody MedicoRequest d){Medico m=obtener(id);return r.save(map(m,d));}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void borrar(@PathVariable Long id){r.delete(obtener(id));}private Medico map(Medico m,MedicoRequest d){m.setCmp(d.cmp());m.setNombres(d.nombres());m.setApellidos(d.apellidos());m.setTelefono(d.telefono());m.setCorreo(d.correo());m.setEstado(d.estado());m.setEspecialidad(er.findById(d.idEspecialidad()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Especialidad inexistente")));return m;}
public record MedicoRequest(@jakarta.validation.constraints.NotBlank String cmp,@jakarta.validation.constraints.NotBlank String nombres,@jakarta.validation.constraints.NotBlank String apellidos,String telefono,@jakarta.validation.constraints.Email String correo,@jakarta.validation.constraints.NotNull Long idEspecialidad,String estado){}
}
